 * LVGL v9.5.0 PC Simulator with SDL2
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include "lvgl/lvgl.h"
#include "lvgl/demos/lv_demos.h"

/*********************
 *      DEFINES
 *********************/
#define SDL_HOR_RES 320
#define SDL_VER_RES 240

/**********************
 *  STATIC VARIABLES
 **********************/
static lv_display_t *disp;
static lv_indev_t *mouse;
static lv_indev_t *mousewheel;
static lv_indev_t *keyboard;

static SDL_Window *window;
static SDL_Renderer *renderer;
static SDL_Texture *texture;

static uint32_t ticks(void)
{
    return SDL_GetTicks();
}

static void hal_init(void)
{
    /* SDL init */
    SDL_Init(SDL_INIT_VIDEO);
    window = SDL_CreateWindow("LVGL Simulator",
                              SDL_WINDOWPOS_UNDEFINED,
                              SDL_WINDOWPOS_UNDEFINED,
                              SDL_HOR_RES, SDL_VER_RES,
                              SDL_WINDOW_SHOWN | SDL_WINDOW_RESIZABLE);
    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    texture = SDL_CreateTexture(renderer,
                                SDL_PIXELFORMAT_ARGB8888,
                                SDL_TEXTUREACCESS_TARGET,
                                SDL_HOR_RES, SDL_VER_RES);

    /* LVGL display init */
    static lv_color_t buf[SDL_HOR_RES * 10];
    lv_display_t *disp = lv_display_create(SDL_HOR_RES, SDL_VER_RES);
    lv_display_set_flush_cb(disp, NULL); /* Will be set by SDL driver */
    lv_display_set_buffers(disp, buf, NULL, sizeof(buf), LV_DISPLAY_RENDER_MODE_PARTIAL);

    /* Mouse init */
    mouse = lv_sdl_mouse_create();

    /* Mousewheel init */
    mousewheel = lv_sdl_mousewheel_create();

    /* Keyboard init */
    keyboard = lv_sdl_keyboard_create();
}

int main(int argc, char *argv[])
{
    (void)argc;
    (void)argv;

    /* Initialize LVGL */
    lv_init();

    /* Initialize HAL (display, input devices) */
    hal_init();

    /* Enable demos */
    lv_demo_widgets();
    // lv_demo_benchmark();
    // lv_demo_music();
    // lv_demo_stress();

    /* Main loop */
    while (1) {
        SDL_Delay(lv_timer_handler());
    }

    return 0;
}

